// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.noteimport com.roshan.persona.productivity.alarm.EncryptedData/** * NOUS — Note Data Models (Module 14 v1.2 — Step 14.3). * * Data structures for notes (encrypted at rest via [NoteEncryptionHelper], * searchable via FTS5 full-text index built from the stripped plain text). * * ## Encryption Model * * - The note **body** is stored as [EncryptedData] (AES-256-GCM IV + ciphertext). * - The note **title** and **plain-text body** (markdown stripped) are stored *   unencrypted because they must be indexed by FTS5 for search. To preserve *   privacy, the FTS index lives in a SQLCipher-encrypted database file — so *   search text is encrypted at the file-system level even though it isn't *   field-level encrypted. * * ## Search Model * * - The stripped plain text (markdown removed) is inserted into an FTS5 *   virtual table `notes_fts` synced with the `notes` table. * - Search uses [com.roshan.persona.productivity.alarm.Fts5Utils.escapeFts5Query] *   to prevent FTS5 operator injection (e.g., a user searching for `*` or `:`). * - Prefix search uses [com.roshan.persona.productivity.alarm.Fts5Utils.buildPrefixQuery] *   to enable "starts with" matching. *//** * A user note (encrypted body + plain-text title for FTS5 search). * * @property id              unique note ID. * @property title           note title (plain text — searchable). * @property encryptedBody   AES-GCM encrypted body (Base64 IV + ciphertext). *                           Null for empty-body notes. * @property plainTextBody   markdown-stripped body for FTS5 indexing *                           (kept in sync with [encryptedBody] via decrypt+strip). * @property contentType     type of content (TEXT / MARKDOWN / CODE / LIST). * @property tags            user-applied tags (e.g., ["work", "urgent"]). * @property createdAtMs     epoch ms when the note was created. * @property updatedAtMs     epoch ms when the note was last updated. */data class NoteInfo(    val id: String,    val title: String,    val encryptedBody: EncryptedData? = null,    val plainTextBody: String = "",    val contentType: NoteContentType = NoteContentType.MARKDOWN,    val tags: List<String> = emptyList(),    val createdAtMs: Long = System.currentTimeMillis(),    val updatedAtMs: Long = System.currentTimeMillis(),) {    /** True if the note body is empty. */    val isEmpty: Boolean get() = title.isBlank() && plainTextBody.isBlank()    /** Word count of the plain-text body (0 if empty). */    fun wordCount(): Int =        if (plainTextBody.isBlank()) 0        else plainTextBody.trim().split(Regex("\\s+")).size    /** Character count of the plain-text body. */    fun charCount(): Int = plainTextBody.length    /** Human-readable summary (first 80 chars of plain text). */    val summary: String        get() = if (plainTextBody.length <= 80) plainTextBody                else plainTextBody.substring(0, 77) + "..."}/** * Type of note content (drives rendering + indexing strategy). */enum class NoteContentType(val displayName: String) {    /** Plain text — no formatting. */    TEXT("Text"),    /** Markdown — rendered to HTML for display, stripped to plain text for FTS. */    MARKDOWN("Markdown"),    /** Code block — preserved verbatim, no markdown stripping. */    CODE("Code"),    /** Checklist / list — markdown bullets, stripped to plain text for FTS. */    LIST("List"),}/** * Result of a search query. * * @property note       the matched note. * @property snippet    short excerpt around the match (for UI display). * @property matchCount number of matches in this note. * @property score      FTS5 rank score (lower = better match). */data class NoteSearchResult(    val note: NoteInfo,    val snippet: String,    val matchCount: Int = 1,    val score: Double = 0.0,)/** * Result of note operations (sealed class for async returns). * * Mirrors [com.roshan.persona.productivity.alarm.AlarmResult] + * [com.roshan.persona.productivity.reminder.ReminderResult] for consistency * across the productivity stack. */sealed interface NoteResult<out T> {    data class Success<T>(val data: T, val spokenMessage: String) : NoteResult<T>    data class Failure(val error: String, val spokenMessage: String) : NoteResult<Nothing>    data class NeedsPermission(val permissions: List<String>, val spokenMessage: String) : NoteResult<Nothing>}// ═══════════════════════════════════════════════════════════════════════════// Note Store (in-memory for v1 — encrypted Room DB in production)// ═══════════════════════════════════════════════════════════════════════════/** * Note Store — manages note state (in-memory for v1). * * Production: encrypted Room database (SQLCipher) with FTS5 virtual table. * Current:    in-memory map (sufficient for v1 unit tests + smoke testing). * * The encrypted body is ALWAYS stored as [EncryptedData] — never as plaintext. * The plain-text body (markdown stripped) is stored unencrypted for FTS5 * indexing, but in production the underlying database file is SQLCipher- * encrypted, so search text is still protected at the file-system level. *//** * NOUS — Note Store interface. * * Abstraction over note persistence. Two implementations: *  - [InMemoryNoteStore] — for tests + early development. *  - [RoomNoteStore] — production, backed by [NoteDao] + SQLCipher-encrypted Room. * * **Previously**: `NoteStore` was a concrete class with an in-memory map. * `NoteEngine` hardcoded the in-memory impl, bypassing SQLCipher entirely. * Audit Task ID: audit-m13-productivity P0. * * @see NoteDao * @see EncryptedNoteDatabase */interface NoteStore {    /** Insert or replace a note. */    fun put(note: NoteInfo)    /** Get a note by ID. */    fun getById(id: String): NoteInfo?    /** Get all notes (newest first). */    fun getAll(): List<NoteInfo>    /** Get notes by tag. */    fun getByTag(tag: String): List<NoteInfo>    /** Delete a note by ID. Returns true if a note was removed. */    fun deleteById(id: String): Boolean    /** Full-text search over note titles + plain-text bodies. */    fun search(query: String): List<NoteInfo>    /** Prefix search — "starts with" matching. */    fun searchPrefix(query: String): List<NoteInfo>    /** Get total note count. */    fun count(): Int    /** Clear all notes (used by tests). */    fun clear()}/** * In-memory note store (for tests + early development). * * Uses a mutable map — data is lost on process death. */class InMemoryNoteStore : NoteStore {    private val notes = mutableMapOf<String, NoteInfo>()    override fun put(note: NoteInfo) {        notes[note.id] = note    }    override fun getById(id: String): NoteInfo? = notes[id]    override fun getAll(): List<NoteInfo> = notes.values.sortedByDescending { it.updatedAtMs }    override fun getByTag(tag: String): List<NoteInfo> =        notes.values.filter { tag in it.tags }.sortedByDescending { it.updatedAtMs }    override fun deleteById(id: String): Boolean = notes.remove(id) != null    override fun search(query: String): List<NoteInfo> {        if (query.isBlank()) return emptyList()        val q = query.trim().lowercase()        return notes.values            .filter {                it.title.lowercase().contains(q) ||                it.plainTextBody.lowercase().contains(q) ||                it.tags.any { tag -> tag.lowercase().contains(q) }            }            .sortedByDescending { it.updatedAtMs }    }    override fun searchPrefix(query: String): List<NoteInfo> {        if (query.isBlank()) return emptyList()        val q = query.trim().lowercase()        return notes.values            .filter {                it.title.lowercase().startsWith(q) ||                it.plainTextBody.lowercase().startsWith(q) ||                it.plainTextBody.lowercase().contains(" $q") ||                it.tags.any { tag -> tag.lowercase().startsWith(q) }            }            .sortedByDescending { it.updatedAtMs }    }    override fun count(): Int = notes.size    override fun clear() = notes.clear()}/** * Backwards-compatible default NoteStore (in-memory). * * Kept so existing `NoteEngine(noteStore = NoteStore())` calls compile. */fun NoteStore(): NoteStore = InMemoryNoteStore()